16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
67	    private Set<Pet> pets;
68	
69	    public String getAddress() {
70	        return this.address;
71	    }
72	
73	    public void setAddress(String address) {
74	        this.address = address;
75	    }
76	
77	    public String getCity() {
78	        return this.city;
79	    }
80	
81	    public void setCity(String city) {
82	        this.city = city;
83	    }
84	
85	    public String getTelephone() {
86	        return this.telephone;
87	    }
88	
89	    public void setTelephone(String telephone) {
90	        this.telephone = telephone;
91	    }
92	
93	    public String getEmail() {
94	        return this.email;
95	    }
96	
97	    public void setEmail(String email) {
98	        this.email = email;
99	    }
100	
101	    public LocalDate getRegistrationDate() {
102	        return this.registrationDate;
103	    }
104	
105	    public void setRegistrationDate(LocalDate registrationDate) {
106	        this.registrationDate = registrationDate;
107	    }
108	
109	    public String getCustomerCode() {
110	        return this.customerCode;
111	    }
112	
113	    public void setCustomerCode(String customerCode) {
114	        this.customerCode = customerCode;
115	    }
116	
117	    public String getHouseholdId() {
118	        return this.householdId;
119	    }
120	
121	    public void setHouseholdId(String householdId) {
122	        this.householdId = householdId;
123	    }
124	
125	    public Integer getNamesakeCount() {
126	        return this.namesakeCount;
127	    }
128	
129	    public void setNamesakeCount(Integer namesakeCount) {
130	        this.namesakeCount = namesakeCount;
131	    }
132	
133	    protected Set<Pet> getPetsInternal() {
134	        if (this.pets == null) {
135	            this.pets = new HashSet<>();
136	        }
137	        return this.pets;
138	    }
139	
140	    protected void setPetsInternal(Set<Pet> pets) {
141	        this.pets = pets;
142	    }
143	
144	    public List<Pet> getPets() {
145	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
146	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
147	        return Collections.unmodifiableList(sortedPets);
148	    }
149	
150	    public void setPets(List<Pet> pets) {
151	        this.pets = new HashSet<>(pets);
152	    }
153	
154	    public void addPet(Pet pet) {
155	        getPetsInternal().add(pet);
156	        pet.setOwner(this);
157	    }
158	
159	    /**
160	     * Return the Pet with the given name, or null if none found for this Owner.
161	     *
162	     * @param name to test
163	     * @return true if pet name is already in use
164	     */
165	    public Pet getPet(String name) {
166	        return getPet(name, false);
167	    }
168	
169	    /**
170	     * Return the Pet with the given name, or null if none found for this Owner.
171	     *
172	     * @param name to test
173	     * @return true if pet name is already in use
174	     */
175	    public Pet getPet(String name, boolean ignoreNew) {
176	        name = name.toLowerCase();
177	        for (Pet pet : getPetsInternal()) {
178	            if (!ignoreNew || !pet.isNew()) {
179	                String compName = pet.getName();
180	                compName = compName.toLowerCase();
181	                if (compName.equals(name)) {
182	                    return pet;
183	                }
184	            }
185	        }
186	        return null;
187	    }
188	
189	    public Pet getPet(Integer petId) {
190	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
191	    }
192	
193	    @Override
194	    public String toString() {
195	        return new ToStringCreator(this)
196	
197	            .append("id", this.getId())
198	            .append("new", this.isNew())
199	            .append("lastName", this.getLastName())
200	            .append("firstName", this.getFirstName())
201	            .append("address", this.address)
202	            .append("city", this.city)
203	            .append("telephone", this.telephone)
204	            .append("email", this.email)
205	            .append("registrationDate", this.registrationDate)
206	            .append("customerCode", this.customerCode)
207	            .append("householdId", this.householdId)
208	            .append("namesakeCount", this.namesakeCount)
209	            .toString();
210	    }
211	}
