287	    private <T> T findEntityById(Supplier<T> supplier) {
288	        try {
289	            return supplier.get();
290	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
291	            // Just ignore not found exceptions for Jdbc/Jpa realization
292	            return null;
293	        }
294	    }
