64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    private final OwnerFieldsValidator ownerFieldsValidator;
79	
80	    private final HouseholdDuplicateValidator householdDuplicateValidator;
81	
82	    private final HouseholdIdGenerator householdIdGenerator;
83	
84	    private final TelephoneNormalizer telephoneNormalizer;
85	
86	    private final EmailNormalizer emailNormalizer;
87	
88	    private final AddressNormalizer addressNormalizer;
89	
90	    private final CustomerCodeGenerator customerCodeGenerator;
91	
92	    private final NamesakeCounter namesakeCounter;
93	
94	    public OwnerRestControllerV1(ClinicService clinicService,
95	                                 OwnerMapper ownerMapper,
96	                                 PetMapper petMapper,
97	                                 VisitMapper visitMapper,
98	                                 OwnerFieldsValidator ownerFieldsValidator,
99	                                 HouseholdDuplicateValidator householdDuplicateValidator,
100	                                 HouseholdIdGenerator householdIdGenerator,
101	                                 TelephoneNormalizer telephoneNormalizer,
102	                                 EmailNormalizer emailNormalizer,
103	                                 AddressNormalizer addressNormalizer,
104	                                 CustomerCodeGenerator customerCodeGenerator,
105	                                 NamesakeCounter namesakeCounter) {
106	        this.clinicService = clinicService;
107	        this.ownerMapper = ownerMapper;
108	        this.petMapper = petMapper;
109	        this.visitMapper = visitMapper;
110	        this.ownerFieldsValidator = ownerFieldsValidator;
111	        this.householdDuplicateValidator = householdDuplicateValidator;
112	        this.householdIdGenerator = householdIdGenerator;
113	        this.telephoneNormalizer = telephoneNormalizer;
114	        this.emailNormalizer = emailNormalizer;
115	        this.addressNormalizer = addressNormalizer;
116	        this.customerCodeGenerator = customerCodeGenerator;
117	        this.namesakeCounter = namesakeCounter;
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
123	        Collection<Owner> owners;
124	        if (lastName != null) {
125	            owners = this.clinicService.findOwnerByLastName(lastName);
126	        } else {
127	            owners = this.clinicService.findAllOwners();
128	        }
129	        if (owners.isEmpty()) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
138	        Owner owner = this.clinicService.findOwnerById(ownerId);
139	        if (owner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
148	        if (ownerFieldsDto != null) {
149	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
150	        }
151	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
152	        if (!missingFields.isEmpty()) {
153	            throw new MissingOwnerFieldsException(missingFields);
154	        }
155	        HttpHeaders headers = new HttpHeaders();
156	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
157	        Collection<Owner> sameLastName =
158	            this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
159	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
160	        applyHouseholdPolicy(owner, ownerFieldsDto, sameLastName);
161	        String normalizedTelephone = telephoneNormalizer.normalize(owner.getTelephone());
162	        if (!this.clinicService.findOwnersByTelephone(normalizedTelephone).isEmpty()) {
163	            throw new DuplicateTelephoneException(normalizedTelephone);
164	        }
165	        owner.setTelephone(normalizedTelephone);
166	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
167	        if (owner.getRegistrationDate() == null) {
168	            owner.setRegistrationDate(LocalDate.now());
169	        }
170	        LocalDate registrationDate = owner.getRegistrationDate();
171	        if (clinicService.countOwnersByRegistrationDate(registrationDate)
172	                >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
173	            throw new DailyOwnerLimitException(registrationDate);
174	        }
175	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
176	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
177	            throw new CityOwnerLimitException(owner.getCity());
178	        }
179	        owner.setCustomerCode(customerCodeGenerator.generate(
