188	    /**
189	     * Applies the household rule to an owner about to be created. When the owner shares a
190	     * household (same last name and address, compared case-insensitively with collapsed
191	     * whitespace) with an existing owner, creation is rejected unless the request opted in via
192	     * {@code sharesHousehold}. When it opts in, the new owner and every existing household
193	     * member are stamped with the same stable {@code householdId}.
194	     *
195	     * @throws DuplicateHouseholdException if a conflicting owner exists and the caller did not opt in
196	     */
197	    private void applyHouseholdPolicy(Owner owner, OwnerFieldsDto ownerFieldsDto, Collection<Owner> sameLastName) {
198	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
199	        if (members.isEmpty()) {
200	            return;
201	        }
202	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
203	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
204	        }
205	        String householdId = householdIdGenerator.generate(owner);
206	        owner.setHouseholdId(householdId);
207	        for (Owner member : members) {
208	            if (!householdId.equals(member.getHouseholdId())) {
209	                member.setHouseholdId(householdId);
210	                this.clinicService.saveOwner(member);
211	            }
212	        }
213	    }
